def compute(vars):
    operating_ratio_2010 = vars["v1"]
    improvement_2010 = vars["v2"]
    expected_operating_ratio_2011 = operating_ratio_2010 - improvement_2010

    return {
        "value": expected_operating_ratio_2011,
        "trace": {
            "operating_ratio_2010": operating_ratio_2010,
            "improvement_2010": improvement_2010,
            "expected_operating_ratio_2011": expected_operating_ratio_2011,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
